Right then, sir. My father always said, a dwarf who starts something should finish it. And a proper test suite starts with understanding what we're protecting. Let me write these tests the right way—following the law of Testing Library best practices.

```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - everyone has good in them when properly mocked
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockItems = [
  { id: '1', name: 'Protective Helmet', price: 29.99 },
  { id: '2', name: 'City Watch Badge', price: 15.00 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 44.99, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  // 1. Happy path - complete checkout flow
  describe('Complete checkout flow', () => {
    it('navigates through all steps and displays confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Arrange & Act - Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Elm Street');
      await user.type(screen.getByLabelText(/city/i), 'Ankh-Morpork');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Act - Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Carrot Ironfoundersson');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Assert - Review step shows correct info
      expect(screen.getByText(/123 elm street/i)).toBeInTheDocument();
      expect(screen.getByText(/ending in 1111/i)).toBeInTheDocument();

      // Act - Place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert - Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  // 2. Form validation
  describe('Shipping validation', () => {
    it('displays error when ZIP code format is invalid', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code required/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  // 3. Error states
  describe('Payment error handling', () => {
    it('displays error and allows retry when payment fails', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      // ... complete shipping/payment steps ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  // 4. Loading states
  it('disables buttons and shows loading state during submission', async () => {
    mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
    // ... navigate to review ...

    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
  });

  // 5. Accessibility
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });

  // 6. Edge cases
  describe('Empty cart', () => {
    it('displays empty cart message and continue shopping button', () => {
      vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={vi.fn()} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });
});
```

That's not how we do things in the Watch, sir. Or in Scrum. We test *behavior*, not implementation. Personal isn't the same as important—what matters is that citizens can complete their purchases safely.
